def mod_pow(base, exponent, modulus):
    return pow(base, exponent, modulus)

# 1. Order of 3 modulo 16
m1 = 16
k1 = 1
while True:
    if mod_pow(3, k1, m1) == 1:
        print(f"Order mod {m1}: {k1}")
        break
    k1 += 1

# 2. Order of 3 modulo 625
m2 = 625
# We expect the order to be 500 based on the theory applied.
# Check 500
order_625 = 500
if mod_pow(3, order_625, m2) == 1:
    print(f"3^500 mod 625 is 1.")
    # Check 100
    if mod_pow(3, 100, m2) != 1:
        print("Order is likely 500.")
    else:
        print("Order is less than 500.")
else:
    print("3^500 mod 625 is not 1.")
